    60	/**
    61	 *  Implementation of a cached stream buffer.
    62	 */
    63	template<class T>
    64	class IOStreamBuffer {
    65	public:
    66	    /// @brief  The class constructor.
    67	    IOStreamBuffer( size_t cache = 4096 * 4096 );
    68	
    69	    /// @brief  The class destructor.
    70	    ~IOStreamBuffer();
    71	
    72	    /// @brief  Will open the cached access for a given stream.
    73	    /// @param  stream      The stream to cache.
    74	    /// @return true if successful.
    75	    bool open( IOStream *stream );
    76	
    77	    /// @brief  Will close the cached access.
    78	    /// @return true if successful.
    79	    bool close();
    80	
    81	    /// @brief  Returns the file-size.
    82	    /// @return The file-size.
    83	    size_t size() const;
    84	    
    85	    /// @brief  Returns the cache size.
    86	    /// @return The cache size.
    87	    size_t cacheSize() const;
    88	
    89	    /// @brief  Will read the next block.
    90	    /// @return true if successful.
    91	    bool readNextBlock();
    92	
    93	    /// @brief  Returns the number of blocks to read.
    94	    /// @return The number of blocks.
    95	    size_t getNumBlocks() const;
    96	
    97	    /// @brief  Returns the current block index.
    98	    /// @return The current block index.
    99	    size_t getCurrentBlockIndex() const;
   100	
   101	    /// @brief  Returns the current file pos.
   102	    /// @return The current file pos.
   103	    size_t getFilePos() const;
   104	
   105	    /// @brief  Will read the next line.
   106	    /// @param  buffer      The buffer for the next line.
   107	    /// @return true if successful.
   108	    bool getNextDataLine( std::vector<T> &buffer, T continuationToken );
   109	
   110	    /// @brief  Will read the next line ascii or binary end line char.
   111	    /// @param  buffer      The buffer for the next line.
   112	    /// @return true if successful.
   113	    bool getNextLine(std::vector<T> &buffer);
   114	
   115	    /// @brief  Will read the next block.
   116	    /// @param  buffer      The buffer for the next block.
