   131	template<class T>
   132	AI_FORCE_INLINE
   133	IOStreamBuffer<T>::IOStreamBuffer( size_t cache )
   134	: m_stream( nullptr )
   135	, m_filesize( 0 )
   136	, m_cacheSize( cache )
   137	, m_numBlocks( 0 )
   138	, m_blockIdx( 0 )
   139	, m_cachePos( 0 )
   140	, m_filePos( 0 ) {
   141	    m_cache.resize( cache );
   142	    std::fill( m_cache.begin(), m_cache.end(), '\n' );
   143	}
   144	
   145	template<class T>
   146	AI_FORCE_INLINE
   147	IOStreamBuffer<T>::~IOStreamBuffer() {
   148	    // empty
   149	}
