   151	template<class T>
   152	AI_FORCE_INLINE
   153	bool IOStreamBuffer<T>::open( IOStream *stream ) {
   154	    //  file still opened!
   155	    if ( nullptr != m_stream ) {
   156	        return false;
   157	    }
   158	
   159	    //  Invalid stream pointer
   160	    if ( nullptr == stream ) {
   161	        return false;
   162	    }
   163	
   164	    m_stream = stream;
   165	    m_filesize = m_stream->FileSize();
   166	    if ( m_filesize == 0 ) {
   167	        return false;
   168	    }
   169	    if ( m_filesize < m_cacheSize ) {
   170	        m_cacheSize = m_filesize;
   171	    }
   172	
   173	    m_numBlocks = m_filesize / m_cacheSize;
   174	    if ( ( m_filesize % m_cacheSize ) > 0 ) {
   175	        m_numBlocks++;
   176	    }
   177	
   178	    return true;
   179	}
   180	
   181	template<class T>
   182	AI_FORCE_INLINE
   183	bool IOStreamBuffer<T>::close() {
   184	    if ( nullptr == m_stream ) {
   185	        return false;
   186	    }
   187	
   188	    // init counters and state vars
   189	    m_stream    = nullptr;
   190	    m_filesize  = 0;
   191	    m_numBlocks = 0;
   192	    m_blockIdx  = 0;
   193	    m_cachePos  = 0;
   194	    m_filePos   = 0;
   195	
   196	    return true;
   197	}
